import numpy as np
from scipy.optimize import least_squares
y=dP_dt
gforms={
 'pow_exp': lambda k,p: 1-np.exp(-k*t**p),
 'hill': lambda k,p: t**p/(k+t**p),
 'expinv': lambda k,p: np.exp(-k/t**p),
}
for nm,gf in gforms.items():
    def f(q):
        g=gf(q[0],q[10])
        return g*(q[1]+q[2]*P+q[3]*P**2+q[4]*P**3) + (q[5]+q[6]*P+q[7]*P**2+q[8]*P**3) + q[9]*P*t
    best=None
    for s in range(25):
        rs=np.random.RandomState(s)
        p0=np.concatenate([[rs.uniform(0.1,2)],rs.uniform(-1,1,9),[rs.uniform(0.5,2)]])
        try:
            r=least_squares(lambda q: f(q)-y,p0,bounds=([0.001]+[-50]*9+[0.1],[50]+[50]*9+[3]))
            if best is None or r.cost<best.cost: best=r
        except Exception: pass
    if best is not None: print(nm,'NMSE',(2*best.cost/len(y)/np.var(y)).round(8),best.x.round(3))
    else: print(nm,'fail')
